package com.schooloss.fullnative.feature.results;
import android.os.Bundle;import android.view.*;import android.widget.*;import com.schooloss.fullnative.core.*;import org.json.*;
public final class ResultDetailActivity extends BaseActivity {
 private int id;private String kind;@Override protected void onCreate(Bundle b){super.onCreate(b);id=getIntent().getIntExtra("id",0);kind=getIntent().getStringExtra("kind");loading("Opening result","Loading published SchoolOS result…");load();}
 private void load(){io.execute(()->{try{JSONObject r=api.get("result_detail","kind="+kind+"&id="+id);JSONObject d=r.optJSONObject("data");runOnUiThread(()->render(d));}catch(Exception e){runOnUiThread(()->error("Could not open result",e,this::load));}});}
 private void render(JSONObject d){LinearLayout p=Ui.v(this);p.setPadding(Ui.dp(this,14),Ui.dp(this,12),Ui.dp(this,14),Ui.dp(this,24));p.setBackgroundColor(Constants.BG);TextView back=Ui.text(this,"‹  Results",12,Constants.BLUE,true);back.setOnClickListener(v->finish());p.addView(back);p.addView(Ui.text(this,d==null?"Result":d.optString("title","Result"),23,Constants.TEXT,true));p.addView(Ui.text(this,d==null?"":d.optString("subtitle",""),10,Constants.MUTED,false));if(d!=null)p.addView(Ui.text(this,String.format(java.util.Locale.US,"%.1f%%",d.optDouble("percentage",0)),30,Constants.BLUE,true));JSONArray a=d==null?null:d.optJSONArray("subjects");if(a!=null)for(int i=0;i<a.length();i++){JSONObject s=a.optJSONObject(i);com.google.android.material.card.MaterialCardView c=Ui.card(this);LinearLayout in=Ui.v(this);in.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,10));in.addView(Ui.text(this,s.optString("subject","Subject"),13,Constants.TEXT,true));in.addView(Ui.text(this,s.toString(),9,Constants.MUTED,false));c.addView(in);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.topMargin=Ui.dp(this,7);p.addView(c,lp);}ScrollView sc=new ScrollView(this);sc.addView(p);setContentView(sc);}
}